  assign sig_in_cdc_from = ctl_rx_wdt_disable_0;
  LUT3 #(
    .INIT(8'h08)) 
    master_watchdog_barking_0_i_1
       (.I0(master_watchdog_0_reg_26_sn_1),
        .I1(master_watchdog_0_reg_2_sn_1),
        .I2(s_out_d4),
        .O(master_watchdog_barking_00));
  LUT6 #(
    .INIT(64'h0000000200000000)) 
    master_watchdog_barking_0_i_2
       (.I0(master_watchdog_barking_0_i_4_n_0),
        .I1(master_watchdog_0_reg[26]),
        .I2(master_watchdog_0_reg[25]),
        .I3(master_watchdog_0_reg[24]),
